// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 count, uint256 amount) public {
        count = bound(count, 1, 10);
        amount = bound(amount, 1 wei, 1 ether);

        address actor = makeAddr("actor");
        vm.deal(actor, amount * count);

        vm.startPrank(actor);
        for (uint256 i = 0; i < count; i++) {
            (bool ok, ) = address(c).call{value: amount}("");
            require(ok, "deposit failed");
        }
        vm.stopPrank();

        assertEq(c.depositsCount(), count);
    }
}
